AsciiString DataChunkInput::openDataChunk(DataChunkVersionType *version)
{
	InputChunk *chunk = new InputChunk;
	chunk->m_id = 0;
	chunk->m_version = 0;
	chunk->m_dataSize = 0;
	m_file->read(&chunk->m_id, 4);
	decrementDataLeft(4);
	m_file->read(&chunk->m_version, 2);
	decrementDataLeft(2);
	m_file->read(&chunk->m_dataSize, 4);
	decrementDataLeft(4);
	chunk->m_dataLeft = chunk->m_dataSize;
	chunk->m_filePos = m_file->tell();
	*version = chunk->m_version;
	chunk->m_next = m_chunkStack;
	m_chunkStack = chunk;
	if (m_file->eof())
		return AsciiString("");
	return m_contents.getName(chunk->m_id);
}

