// FUNCTION: BFME2 0x00307779 size=103 name=?registerParser@DataChunkInput@@QAEPAVUserParser@@ABVAsciiString@@0P6A_NAAV1@PAUDataChunkInfo@@PAX@Z3@Z evidence=N:ledger
UserParser *DataChunkInput::registerParser(const AsciiString &label, const AsciiString &parentLabel, DataChunkParserPtr parser, void *userData)
{
	UserParser *p = new UserParser;
	p->m_label = label;
	p->m_parentLabel = parentLabel;
	p->m_parser = parser;
	UserParser **head = &m_parserList;
	p->m_userData = userData;
	UserParser *first = *head;
	p->m_next = first;
	if (first)
		first->m_link = &p->m_next;
	p->m_link = head;
	*head = p;
	return p;
}

