// FUNCTION: BFME2 0x00307A6A size=86 name=?allocateID@DataChunkTableOfContents@@QAEIABVAsciiString@@@Z evidence=N:ledger
UnsignedInt DataChunkTableOfContents::allocateID(const AsciiString &name)
{
	Mapping *mapping = findMapping(name);
	if (mapping)
		return mapping->m_id;
	mapping = new Mapping;
	mapping->m_id = m_nextID++;
	mapping->m_name = name;
	mapping->m_next = m_list;
	m_list = mapping;
	m_listLength++;
	return mapping->m_id;
}

// FUNCTION: BFME2 0x00307AC0 size=387 name=?parse@DataChunkInput@@QAE_NPAX@Z evidence=N:ledger
Bool DataChunkInput::parse(void *userData)
{
	AsciiString label;
	AsciiString parentLabel;
	DataChunkVersionType ver;
	UserParser *parser;
	DataChunkInfo info;

	if (!m_contents.isOpenedForRead())
		return false;
	if (m_chunkStack)
		parentLabel = m_contents.getName(m_chunkStack->m_id);
	while (m_file->eof() == false)
	{
		if (m_chunkStack)
		{
			if (m_chunkStack->m_dataLeft < 4)
				break;
		}
		label = openDataChunk(&ver);
		if (m_file->eof())
			break;
		for (parser = m_parserList; parser; parser = parser->m_next)
		{
			if (parser->m_label.compare(label) == 0 && parentLabel.compare(parser->m_parentLabel) == 0)
			{
				info.m_label = label;
				info.m_parentLabel = parentLabel;
				info.m_version = ver;
				info.m_dataSize = getChunkDataSize();
				if (parser->m_parser(*this, &info, parser->m_userData ? parser->m_userData : userData) == false)
					return false;
				break;
			}
		}
		closeDataChunk();
	}
	return true;
}

// FUNCTION: BFME2 0x00307C76 size=179 name=?openDataChunk@DataChunkOutput@@QAEXPADG@Z evidence=N:ledger
void DataChunkOutput::openDataChunk(char *name, DataChunkVersionType version)
{
	UnsignedInt id = m_contents.allocateID(AsciiString(name));
	OutputChunk *chunk = new OutputChunk;
	chunk->m_next = m_chunkStack;
	m_chunkStack = chunk;
	chunk->m_id = id;
	::fwrite(&id, 4, 1, m_tmp_file);
	::fwrite(&version, 2, 1, m_tmp_file);
	chunk->m_fileStart = ::ftell(m_tmp_file);
	Int placeholder = 0xFFFF;
	::fwrite(&placeholder, 4, 1, m_tmp_file);
}

// FUNCTION: BFME2 0x00307D29 size=92 name=?writeNameKey@DataChunkOutput@@QAEXW4NameKeyType@@@Z evidence=N:ledger
void DataChunkOutput::writeNameKey(NameKeyType key)
{
	AsciiString name = TheNameKeyGenerator->keyToName(key);
	writeInt((m_contents.allocateID(name) << 8) | 3);
}

// FUNCTION: BFME2 0x00307D85 size=343 name=?writeDict@DataChunkOutput@@QAEXABVDict@@@Z evidence=N:ledger
void DataChunkOutput::writeDict(const Dict &d)
{
	UnsignedShort len = d.getPairCount();
	::fwrite(&len, 2, 1, m_tmp_file);
	for (Int i = 0; i < len; i++)
	{
		NameKeyType k = d.getNthKey(i);
		AsciiString kname = TheNameKeyGenerator->keyToName(k);
		Int keyAndType = m_contents.allocateID(kname);
		keyAndType <<= 8;
		Dict::DataType t = d.getNthType(i);
		keyAndType |= (t & 0xff);
		writeInt(keyAndType);
		switch (t)
		{
		case Dict::DICT_BOOL:
			writeByte(d.getNthBool(i) ? true : false);
			break;
		case Dict::DICT_INT:
			writeInt(d.getNthInt(i));
			break;
		case Dict::DICT_REAL:
			writeReal(d.getNthReal(i));
			break;
		case Dict::DICT_ASCIISTRING:
			writeAsciiString(d.getNthAsciiString(i));
			break;
		case Dict::DICT_UNICODESTRING:
			writeUnicodeString(d.getNthUnicodeString(i));
			break;
		}
	}
}

